[
  {
    "op": "add",
    "collection": "nodes",
    "id": "source-4",
    "value": {
      "type": "source",
      "text": "Session paraphrase: Blake stated the steward chooses what the next work should be; after the steward has chosen, the orchestrator can insert the record for that already chosen work; the orchestrator may ask the steward before stopping. Blake asked that this be captured without broadening.",
      "status": "recorded",
      "meta": {
        "source_kind": "session-paraphrase"
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "orchestrator-inserts-chosen-record",
    "value": {
      "type": "claim",
      "text": "After the steward has chosen the next work, the orchestrator may insert the record for that already chosen work. Inserting the record does not include choosing the work.",
      "status": "accepted",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "rationale": "Separates mechanical record insertion from the choice of next work, which remains with the steward."
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "orchestrator-may-ask-before-stopping",
    "value": {
      "type": "claim",
      "text": "The orchestrator may ask the steward before stopping. This is permissive; it does not establish that asking is required.",
      "status": "accepted",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "rationale": "Recorded as stated. Whether consultation is mandatory remains an open question."
      }
    }
  },
  {
    "op": "update",
    "collection": "nodes",
    "id": "steward-next-work",
    "value": {
      "type": "claim",
      "text": "Steward always chooses next work after a failed attempt.",
      "status": "accepted",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-2",
          "source-4"
        ],
        "rationale": "Keep a clean responsibility boundary; orchestrator may end a failed attempt and return it to steward. Restated by Blake in source-4."
      }
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "source-steward-next-work-1",
